function sayHello(name) {
  var text = 'Hello ' + name; // Local variable in outer scope

  var printName = function() {
    console.log(text); // Accesses outer scope variable
  };

  return printName; // Returns the inner function
}

// Execution:
var say = sayHello('Sandeep');
say(); // Output: 'Hello Sandeep' (closure keeps 'text' alive!)

function createCounter() {
  let count = 0; // Private state

  return {
    increment: () => ++count,
    decrement: () => --count,
    getCount: () => count
  };
}

const counter = createCounter();
console.log(counter.increment()); // 1
console.log(counter.increment()); // 2
console.log(counter.getCount());  // 2

app.service('myService', function() {
  this.sayHello = function(name) {
    return 'Hello ' + name;
  };
});

app.factory('myFactory', function() {
  var factoryObj = {};
  factoryObj.sayHello = function(name) {
    return 'Hello ' + name;
  };
  return factoryObj;
});

app.provider('myProvider', function() {
  var greeting = 'Hello';

  this.setGreeting = function(val) {
    greeting = val;
  };

  this.$get = function() {
    return {
      sayHello: function(name) {
        return greeting + ' ' + name;
      }
    };
  };
});
